1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using TicketClassifier.Models;
4. 
5. namespace TicketClassifier.Services;
6. 
7. public class TicketClassifierService
8. {
9.     private readonly MLContext _mlContext;
10.     private readonly ITransformer _model;
11.     private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
12.     private readonly EvaluationMetrics _evaluationMetrics;
13.     private readonly string[] _classLabels;
14. 
15.     public TicketClassifierService(string dataPath)
16.     {
17.         _mlContext = new MLContext(seed: 0);
18. 
19.         IDataView dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
20.             dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
21. 
22.         var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label")
23.             .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
24.             .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
25.             .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
26.             .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
27.             .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
28.             .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
29. 
30.         _model = pipeline.Fit(dataView);
31. 
32.         // Evaluate on training data (small dataset — cross-validation not viable)
33.         var predictions = _model.Transform(dataView);
34.         var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);
35.         _evaluationMetrics = new EvaluationMetrics
36.         {
37.             MacroAccuracy = (float)metrics.MacroAccuracy,
38.             MicroAccuracy = (float)metrics.MicroAccuracy,
39.             LogLoss = float.IsFinite((float)metrics.LogLoss) ? (float)metrics.LogLoss : 0f,
40.             LogLossReduction = float.IsFinite((float)metrics.LogLossReduction) ? (float)metrics.LogLossReduction : 0f
41.         };
42. 
43.         _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
44. 
45.         // Extract the ordered class labels from the trained model's label column
46.         var schema = _model.GetOutputSchema(dataView.Schema);
47.         var labelColumn = schema["Label"];
48.         var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
49.         labelColumn.Annotations.GetValue("KeyValues", ref labelBuffer);
50.         _classLabels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();
51.     }
52. 
53.     public TicketPredictionResponse Predict(TicketRequest request)
54.     {
55.         var ticketData = new TicketData
56.         {
57.             Subject = request.Subject,
58.             Description = request.Description,
59.             Priority = request.Priority
60.         };
61. 
62.         var prediction = _predictionEngine.Predict(ticketData);
63. 
64.         var confidence = new Dictionary<string, float>();
65.         for (int i = 0; i < _classLabels.Length && i < prediction.Score.Length; i++)
66.         {
67.             confidence[_classLabels[i]] = prediction.Score[i];
68.         }
69. 
70.         return new TicketPredictionResponse
71.         {
72.             PredictedCategory = prediction.Category,
73.             Confidence = confidence
74.         };
75.     }
76. 
77.     public EvaluationMetrics GetMetrics() => _evaluationMetrics;
78. }
